import { SignInButton } from "@clerk/nextjs";
import { revalidatePath } from "next/cache";
import { currentClerkUserId } from "@/lib/auth";
import { getStore, getTunnels } from "@/lib/runtime";
export const dynamic = "force-dynamic";
async function revoke(formData: FormData) { "use server"; const clerkId = await currentClerkUserId(); if (!clerkId) return; const user = await getStore().getOrCreateUser(clerkId); const daemon = await getStore().getDaemon(String(formData.get("id"))); if (!daemon || daemon.userId !== user.id || daemon.revokedAt) return; await getStore().revokeDaemon(daemon.id, new Date()); await getTunnels().delete(daemon.tunnelId); revalidatePath("/connect"); }
export default async function ConnectPage() { const clerkId = await currentClerkUserId(); if (!clerkId) return <section className="card"><h1>Your daemons</h1><p>Sign in to manage daemons connected to your account.</p>{process.env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY ? <SignInButton mode="modal"><button>Sign in</button></SignInButton> : <p className="error">Set DEV_USER_ID for local use, or configure Clerk.</p>}</section>; const user = await getStore().getOrCreateUser(clerkId); const daemons = await getStore().listDaemons(user.id); return <section className="card"><h1>Your daemons</h1>{daemons.length === 0 ? <p>No daemons are connected yet. Run <code>hexbot connect</code> on a daemon to add one.</p> : daemons.map(daemon => { const online = !!daemon.lastSeenAt && Date.now() - daemon.lastSeenAt.getTime() < 10 * 60_000; return <div className="daemon" key={daemon.id}><div><strong>{daemon.name}</strong><small>{daemon.tunnelHostname} · <span className={online ? "online" : "offline"}>{online ? "Online" : "Offline"}</span></small></div><form action={revoke}><input type="hidden" name="id" value={daemon.id} /><button type="submit">Revoke</button></form></div>; })}</section>; }
